{{- if .Values.migrations.enabled }}
apiVersion: batch/v1
kind: Job
metadata:
  name: {{ include "lobu.fullname" . }}-migrate
  labels:
    {{- include "lobu.labels" . | nindent 4 }}
  annotations:
    "helm.sh/hook": pre-install,pre-upgrade
    "helm.sh/hook-weight": "0"
    "helm.sh/hook-delete-policy": before-hook-creation,hook-succeeded
spec:
  backoffLimit: 1
  {{- if .Release.IsUpgrade }}
  activeDeadlineSeconds: {{ add (mul (int .Values.migrations.quiesceBeforeUpgrade.timeoutSeconds) 2) 600 }}
  {{- end }}
  template:
    metadata:
      labels:
        {{- include "lobu.selectorLabels" . | nindent 8 }}
        app.kubernetes.io/component: migrate
    spec:
      restartPolicy: Never
      {{- if .Release.IsUpgrade }}
      serviceAccountName: {{ include "lobu.fullname" . }}-migration-quiesce
      initContainers:
        - name: install-kubectl
          image: {{ .Values.migrations.quiesceBeforeUpgrade.image }}
          imagePullPolicy: {{ .Values.migrations.quiesceBeforeUpgrade.pullPolicy }}
          command:
            - /bin/sh
            - -ec
            - cp "$(command -v kubectl)" /migration-tools/kubectl
          volumeMounts:
            - name: migration-tools
              mountPath: /migration-tools
      {{- end }}
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: migrate
          image: {{ include "lobu.appImage" . }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          command:
            - /bin/bash
            - -ec
            - |
              {{- if .Values.releaseGates.databasePreflight.enabled }}
              echo "checking migration database connectivity"
              node --input-type=module <<'NODE'
              import postgres from "postgres";

              const databaseUrl = process.env.DATABASE_URL;
              const timeoutSeconds = Number(process.env.DB_PREFLIGHT_TIMEOUT_SECONDS || 10);

              if (!databaseUrl) {
                console.error("ERROR: DATABASE_URL not set");
                process.exit(1);
              }

              const sql = postgres(databaseUrl, {
                max: 1,
                connect_timeout: timeoutSeconds,
                idle_timeout: 1,
                onnotice: () => {},
              });

              try {
                const rows = await sql`select current_database() as database`;
                console.log(`migration database preflight passed (${rows[0]?.database ?? "unknown"})`);
              } catch (error) {
                console.error("ERROR: migration database preflight failed");
                console.error(error instanceof Error ? error.message : String(error));
                process.exit(1);
              } finally {
                await sql.end({ timeout: 1 }).catch(() => {});
              }
              NODE
              {{- end }}
              {{- if .Release.IsUpgrade }}
              set -- /app/start.sh migrate
{{ .Files.Get "files/migrate-upgrade.sh" | nindent 14 }}
              {{- else }}
              exec /app/start.sh migrate
              {{- end }}
          env:
            {{- range $key, $value := .Values.app.env }}
            - name: {{ $key }}
              value: {{ $value | quote }}
            {{- end }}
            {{- if .Values.releaseGates.databasePreflight.enabled }}
            - name: DB_PREFLIGHT_TIMEOUT_SECONDS
              value: {{ .Values.releaseGates.databasePreflight.timeoutSeconds | quote }}
            {{- end }}
            {{- if .Release.IsUpgrade }}
            - name: KUBECTL_BIN
              value: /migration-tools/kubectl
            - name: NAMESPACE
              value: {{ .Release.Namespace | quote }}
            - name: APP_DEPLOYMENT
              value: {{ printf "%s-app" (include "lobu.fullname" .) | quote }}
            - name: APP_SELECTOR
              value: {{ printf "app.kubernetes.io/instance=%s,app.kubernetes.io/component=api" .Release.Name | quote }}
            - name: WORKER_DEPLOYMENT
              value: {{ printf "%s-worker" (include "lobu.fullname" .) | quote }}
            - name: WORKER_SELECTOR
              value: {{ printf "app.kubernetes.io/instance=%s,app.kubernetes.io/component=worker" .Release.Name | quote }}
            - name: QUIESCE_TIMEOUT
              value: {{ printf "%ds" (int .Values.migrations.quiesceBeforeUpgrade.timeoutSeconds) | quote }}
            {{- end }}
            {{- if .Values.migrations.database.existingSecret }}
            {{- if .Values.migrations.database.usePooler }}
            - name: DB_USER
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.migrations.database.existingSecret }}
                  key: username
            - name: DB_PASS
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.migrations.database.existingSecret }}
                  key: password
            - name: DATABASE_URL
              value: "REDACTED .Values.migrations.database.poolerService }}:5432/{{ .Values.migrations.database.name }}?sslmode=disable"
            {{- else }}
            - name: DATABASE_URL
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.migrations.database.existingSecret }}
                  key: {{ .Values.migrations.database.existingSecretKey }}
            {{- end }}
