1	#!/usr/bin/env node
2	/**
3	 * Apply db/migrations/*.sql the way dbmate `up` does, with one important fix:
4	 * `transaction:false` sections run statement-at-a-time so CREATE/DROP INDEX
5	 * CONCURRENTLY is not trapped inside Postgres's implicit multi-statement
6	 * transaction (required when a heal DO precedes CONCURRENTLY in the same file).
7	 *
8	 * Records versions in public.schema_migrations (dbmate-compatible).
9	 *
10	 * Usage:
11	 *   DATABASE_URL=... node scripts/migrate-up.mjs
12	 *   MIGRATIONS_DIR=/app/db/migrations node scripts/migrate-up.mjs
13	 *   DATABASE_URL=... node scripts/migrate-up.mjs --check-pending
14	 *
15	 * --check-pending applies nothing. It reports whether any migration file is
16	 * missing from the ledger and encodes the answer in the exit status, so the
17	 * chart's pre-upgrade hook can skip its scale-to-zero quiesce on the common
18	 * deploy that ships no schema change:
19	 *   0 - at least one migration is pending (the caller must quiesce)
20	 *   3 - the ledger is complete, nothing is pending (safe to skip the quiesce)
21	 *   1 - the answer could not be determined (the caller must quiesce)
22	 * Only the definitive 3 unlocks the fast path; every other status, including a
23	 * crash, leaves the caller quiescing.
24	 */
25	import { readdirSync, readFileSync } from "node:fs";
26	import { join } from "node:path";
27	import postgres from "postgres";
28	
29	const CHECK_PENDING_NONE_EXIT = 3;
30	
31	const checkPendingOnly = process.argv.slice(2).includes("--check-pending");
32	const migrationsDir =
33	  process.env.MIGRATIONS_DIR || join(process.cwd(), "db/migrations");
34	const databaseUrl = process.env.DATABASE_URL;
35	if (!databaseUrl) {
36	  console.error("ERROR: DATABASE_URL not set");
37	  process.exit(1);
38	}
39	
40	function listMigrationFiles(dir) {
41	  const files = readdirSync(dir)
42	    .filter((file) => file.endsWith(".sql"))
43	    .sort();
44	  const ownerByVersion = new Map();
45	  for (const file of files) {
46	    const version = /^(\d+)_[^/]+\.sql$/.exec(file)?.[1];
47	    if (!version) continue;
48	    const owner = ownerByVersion.get(version);
49	    if (owner) {
50	      throw new Error(
51	        `Duplicate migration version ${version}: ${owner} and ${file}. ` +
52	          "Each schema_migrations ledger version must identify exactly one file."
53	      );
54	    }
55	    ownerByVersion.set(version, file);
56	  }
57	  return files;
58	}
59	
60	function parseTransactionOption(markerLine) {
61	  return !/\btransaction\s*:\s*false\b/i.test(markerLine);
62	}
63	
64	function loadMigrationUp(dir, file) {
65	  const content = readFileSync(join(dir, file), "utf-8");
66	  const upMarker = content.match(/^--\s*migrate:up(.*)$/m);
67	  const transaction = parseTransactionOption(upMarker?.[0] ?? "-- migrate:up");
68	  const sql = content
69	    .split(/^--\s*migrate:down.*$/m)[0]
70	    .replace(/^--\s*migrate:up.*$/m, "")
71	    .replace(/^SET transaction_timeout = 0;\s*$/gm, "")
72	    .trim();
73	  return { sql, transaction };
74	}
75	
76	/** Dollar-quote / string-literal aware statement splitter (see migration-loader.ts). */
77	function splitSqlStatements(sql) {
78	  const statements = [];
79	  let current = "";
80	  let i = 0;
81	  const n = sql.length;
82	
83	  const pushCurrent = () => {
84	    const trimmed = current.trim();
85	    if (trimmed) statements.push(trimmed);
86	    current = "";
87	  };
88	
89	  while (i < n) {
90	    const ch = sql[i];
91	    const next = sql[i + 1];
92	
93	    if (ch === "-" && next === "-") {
94	      const end = sql.indexOf("\n", i);
95	      const chunk = end === -1 ? sql.slice(i) : sql.slice(i, end + 1);
96	      current += chunk;
97	      i += chunk.length;
98	      continue;
99	    }
100	
101	    if (ch === "/" && next === "*") {
102	      const end = sql.indexOf("*/", i + 2);
103	      const chunk = end === -1 ? sql.slice(i) : sql.slice(i, end + 2);
104	      current += chunk;
105	      i += chunk.length;
106	      continue;
107	    }
108	
109	    if (ch === "$") {
110	      const tagMatch = sql.slice(i).match(/^\$([A-Za-z_][A-Za-z0-9_]*)?\$/);
111	      if (tagMatch) {
112	        const tag = tagMatch[0];
113	        const close = sql.indexOf(tag, i + tag.length);
114	        if (close === -1) {
115	          current += sql.slice(i);
116	          break;
117	        }
118	        current += sql.slice(i, close + tag.length);
119	        i = close + tag.length;
120	        continue;
121	      }
122	    }
123	
124	    if (ch === "'") {
125	      current += ch;
126	      i += 1;
127	      while (i < n) {
128	        current += sql[i];
129	        if (sql[i] === "'" && sql[i + 1] === "'") {
130	          current += sql[i + 1];
131	          i += 2;
132	          continue;
133	        }
134	        if (sql[i] === "'") {
135	          i += 1;
136	          break;
137	        }
138	        i += 1;
139	      }
140	      continue;
141	    }
142	
143	    if (ch === ";") {
144	      pushCurrent();
145	      i += 1;
146	      continue;
147	    }
148	
149	    current += ch;
150	    i += 1;
151	  }
152	
153	  pushCurrent();
154	  return statements;
155	}
156	
157	async function executeSection(sqlClient, section) {
158	  if (!section.sql.trim()) return;
159	  if (section.transaction) {
160	    await sqlClient.unsafe(section.sql);
161	    return;
162	  }
163	  for (const statement of splitSqlStatements(section.sql)) {
164	    await sqlClient.unsafe(statement);
165	  }
166	}
167	
168	async function recordMigration(sqlClient, version) {
169	  await sqlClient.unsafe(
170	    `INSERT INTO public.schema_migrations (version) VALUES ($1) ON CONFLICT DO NOTHING`,
171	    [version]
172	  );
173	}
174	
175	async function applyMigration(sqlClient, section, version) {
176	  if (section.transaction) {
177	    await sqlClient.begin(async (tx) => {
178	      await executeSection(tx, section);
179	      await recordMigration(tx, version);
180	    });
181	    return;
182	  }
183	
184	  // CONCURRENTLY cannot share a transaction with the ledger write. These
185	  // migrations must therefore remain replay-safe, as dbmate also requires for
186	  // transaction:false migrations interrupted before their version is recorded.
187	  await executeSection(sqlClient, section);
188	  await recordMigration(sqlClient, version);
189	}
190	
191	const migrationFiles = listMigrationFiles(migrationsDir);
192	const sql = postgres(databaseUrl, { max: 1, onnotice: () => undefined });
193	let migrationLockHeld = false;
194	
195	if (checkPendingOnly) {
196	  // Read-only: no ledger table creation and no advisory lock, so this can run
197	  // while the old replicas are still serving. A version present in the ledger
198	  // but absent from disk is not pending — only the other direction blocks.
199	  let pending;
200	  try {
201	    const appliedRows = await sql.unsafe(
202	      `SELECT version FROM public.schema_migrations`
203	    );
204	    const applied = new Set(appliedRows.map((r) => r.version));
205	    pending = migrationFiles.filter(
206	      (file) => !applied.has(file.split("_")[0] ?? "")
207	    );
208	  } catch (error) {
209	    console.error(
210	      `ERROR: could not determine pending migrations: ${
211	        error instanceof Error ? error.message : String(error)
212	      }`
213	    );
214	    await sql.end({ timeout: 1 }).catch(() => undefined);
215	    process.exit(CHECK_PENDING_NONE_EXIT);
216	  }
217	  await sql.end({ timeout: 1 }).catch(() => undefined);
218	  if (pending.length === 0) {
219	    console.log("No pending migrations");
220	    process.exit(CHECK_PENDING_NONE_EXIT);
221	  }
222	  console.log(`Pending migrations (${pending.length}): ${pending.join(", ")}`);
223	  process.exit(0);
224	}
225	
226	try {
227	  await sql.unsafe(`
228	    CREATE TABLE IF NOT EXISTS public.schema_migrations (
229	      version character varying(128) NOT NULL PRIMARY KEY
230	    )
231	  `);
232	
233	  // start.sh runs on every replica. Serialize the ledger read + migration loop
234	  // on one Postgres session so two fresh pods cannot apply the same version.
235	  await sql.unsafe(`SELECT pg_advisory_lock(hashtext('lobu_migrate_up'))`);
236	  migrationLockHeld = true;
237	

